class Solution:
    def canMakeSubsequence(self, s: str, t: str) -> bool:
        m, n = len(s), len(t)
        for p in range(m):
            j, ok = 0, True
            for i in range(p):
                while j < n and t[j] != s[i]:
                    j += 1
                if j == n:
                    ok = False
                    break
                j += 1
            if not ok:
                continue
            k = n - 1
            for i in range(m - 1, p, -1):
                while k > j and t[k] != s[i]:
                    k -= 1
                if k == j:
                    ok = False
                    break
                k -= 1
            if ok:
                return True
        return False

