class Solution {
public:
    bool canMakeSubsequence(string s, string t) {
        int m = s.size(), n = t.size();
        for (int p = 0; p < m; p++) {
            int j = 0; bool ok = true;
            for (int i = 0; i < p && ok; i++) {
                while (j < n && t[j] != s[i]) j++;
                if (j == n) ok = false; else j++;
            }
            if (!ok) continue;
            int k = n - 1;
            for (int i = m - 1; i > p && ok; i--) {
                while (k > j && t[k] != s[i]) k--;
                if (k == j) ok = false; else k--;
            }
            if (ok) return true;
        }
        return false;
    }
};

