class Solution:
    def canMakeSubsequence(self, s: str, t: str) -> bool:
        m, n = len(s), len(t)
        INF = n + 1
        pre = [0] * (m + 1)
        j, bad = 0, False
        for i in range(m):
            if not bad:
                while j < n and t[j] != s[i]:
                    j += 1
                if j == n:
                    bad = True
                else:
                    j += 1
                    pre[i + 1] = j
            if bad:
                pre[i + 1] = INF
        if pre[m] <= n:
            return True
        suf = [-1] * (m + 1)
        suf[m] = n
        for i in range(m - 1, -1, -1):
            k = suf[i + 1] - 1
            while k >= 0 and t[k] != s[i]:
                k -= 1
            suf[i] = k
        return any(pre[p] < suf[p + 1] for p in range(m))

