class Solution {
public:
    bool canMakeSubsequence(string s, string t) {
        int m = s.size(), n = t.size(), INF = n + 1;
        vector<int> pre(m + 1, 0);
        int j = 0; bool bad = false;
        for (int i = 0; i < m; i++) {
            if (!bad) {
                while (j < n && t[j] != s[i]) j++;
                if (j == n) bad = true;
                else pre[i + 1] = ++j;
            }
            if (bad) pre[i + 1] = INF;
        }
        if (pre[m] <= n) return true;
        vector<int> suf(m + 1, -1);
        suf[m] = n;
        for (int i = m - 1; i >= 0; i--) {
            int k = suf[i + 1] - 1;
            while (k >= 0 && t[k] != s[i]) k--;
            suf[i] = k;
        }
        for (int p = 0; p < m; p++)
            if (pre[p] < suf[p + 1]) return true;
        return false;
    }
};

